      if(action==='toggleDevice')B.demoDeviceState(s,tid,x.id,row.type,!B.online(s,x,row.type));if(action==='retry')B.retryCommand(s,tid,x.id);if(action==='deliver')B.deliverRecharge(s,tid,x.id);
