      if(['start','confirm','urge'].includes(action))B.serviceAction(s,tid,x.id,action);
      if(action==='read'){x.read=!x.read}if(action==='toggleTech'){x.active=!x.active;B.log(s,tid,'调整维修人员状态',x.name)}
