      if(k==='credential')return props.role==='agent'?[]:[['@credentialView','查看 / 分享'],['@credentialEdit','改期'],['freeze','冻结'],['restore','恢复'],['revoke','撤销'],...(x.kind==='IC卡'?[['lost','挂失']]:[]),...(x.status==='待同步'?[['retryCredential','重试同步']]:[])];
